org.opencontainers.image.version=${{ env.GHOST_BUILD_VERSION }}

with.script:
github.rest.issues.addLabels({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  labels: ["migration"]
})
